(10, 4, 'Jump Smash Technique', 'Improving timing and power for jump smashes.', '2026-02-06 18:30:00', '2026-02-06 20:30:00', 'Scheduled', '2025-11-19 18:06:31', '2025-11-19 18:06:31'),
